def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    h = max(0, int(horizon))
    if h == 0:
        return []
    y = []
    for value in history:
        try:
            value = float(value)
            if math.isfinite(value):
                y.append(value)
        except (TypeError, ValueError):
            pass
    if not y:
        return [0.0] * h
    p = 19
    n = len(y)
    if n < 2 * p:
        recent = y[-min(12, n):]
        slope = statistics.median([recent[i] - recent[i - 1] for i in range(1, len(recent))]) if len(recent) > 1 else 0.0
        center = statistics.median(recent)
        slope = max(-abs(center) * 0.05, min(abs(center) * 0.05, slope))
        return [float(max(0.0, y[-1] + slope * (k + 1))) for k in range(h)]
    start = max(0, n - 3 * p)
    cycle_diffs = [y[i] - y[i - p] for i in range(start + p, n)]
    cycle_step = statistics.median(cycle_diffs) / p if cycle_diffs else 0.0
    diff_center = statistics.median(cycle_diffs) if cycle_diffs else 0.0
    diff_mad = statistics.median([abs(d - diff_center) for d in cycle_diffs]) if cycle_diffs else 0.0
    if diff_mad > 1.0:
        stable = [d for d in cycle_diffs if abs(d - diff_center) <= 2.5 * diff_mad]
        if stable:
            cycle_step = statistics.median(stable) / p
    templates = {}
    for phase in range(p):
        residuals = [y[i] - cycle_step * i for i in range(start, n) if i % p == phase]
        if residuals:
            templates[phase] = statistics.median(residuals)
    fallback = statistics.median(y[-p:])
    result = []
    for k in range(h):
        t = n + k
        phase = t % p
        estimate = cycle_step * t + templates.get(phase, fallback - cycle_step * (n - 1))
        result.append(float(max(0.0, estimate)))
    return result
